<script>
// ============================================================
// DATA MODEL
// ============================================================
const hashData = [
    { username: 'jsmith', hashType: 'MD5', hash: 'd5c0607301ad5d5c1528962a83992ac8', correctMode: 'dictionary', correctWordlist: 'common', password: 'sunshine1', hashcatMode: '0' },
    { username: 'aharris', hashType: 'MD5', hash: '482c811da5d5b4bc6d497ffa98491e38', correctMode: 'dictionary', correctWordlist: 'common', password: 'password123', hashcatMode: '0' },
    { username: 'rpatel', hashType: 'SHA1', hash: 'f9d373422d452de9456ca851ebb752c3e0bb106e', correctMode: 'rule', correctWordlist: 'rules', password: 'letmein00', hashcatMode: '100' },
    { username: 'mchen', hashType: 'SHA256', hash: '0152f3fd74b6db860b84b8c6063888767931aa352549ae73a6dd829b0a1d6442', correctMode: 'dictionary', correctWordlist: 'company', password: 'Winter2024!', hashcatMode: '1400' },
    { username: 'admin_svc', hashType: 'NTLM', hash: 'b4e3e97dd57682498993e2c19224e07a', correctMode: 'mask', correctWordlist: null, password: 'P@ssw0rd99', hashcatMode: '1000' }
];

const wordlistFiles = { common: 'common-passwords.txt', company: 'company-wordlist.txt', rules: 'rule-mutations.txt' };
const attackModeCodes = { dictionary: '0', rule: '0 -r best64.rule', mask: '3' };

let crackedUsernames = [];

// ============================================================
// ATTACK MODE / WORDLIST INTERLOCK
// ============================================================
document.getElementById('attack-mode-select').addEventListener('change', function() {
    const wordlistSelect = document.getElementById('wordlist-select');
    if (this.value === 'mask') {
        wordlistSelect.disabled = true;
    } else {
        wordlistSelect.disabled = false;
    }
});

// ============================================================
// RUN ATTACK
// ============================================================
function runAttack() {
    const target = document.getElementById('target-select').value;
    const mode = document.getElementById('attack-mode-select').value;
    const wordlist = document.getElementById('wordlist-select').value;
    const entry = hashData.find(h => h.username === target);
    const output = document.getElementById('terminal-output');
    const statusMsg = document.getElementById('status-message');

    if (crackedUsernames.includes(target)) {
        output.textContent = target + ' has already been cracked. Check the Cracked Results panel.';
        return;
    }

    const commandLine = mode === 'mask'
        ? '$ hashcat -m ' + entry.hashcatMode + ' -a 3 nexora_dump.txt ?u?l?s?l?d?l?d?d'
        : '$ hashcat -m ' + entry.hashcatMode + ' -a ' + attackModeCodes[mode] + ' nexora_dump.txt ' + wordlistFiles[wordlist];

    const success = (mode === entry.correctMode) && (mode === 'mask' || wordlist === entry.correctWordlist);

    const lines = [];
    lines.push(commandLine);
    lines.push('Initializing simulated cracking session...');
    lines.push('Target hash: ' + entry.hash);
    lines.push('Hash type: ' + entry.hashType);

    if (success) {
        lines.push('Status: Cracked');
        lines.push(entry.hash + ':' + entry.password);
        output.textContent = lines.join('\n');
        output.style.color = 'var(--success)';

        crackedUsernames.push(target);
        addResultRow(entry, mode);
        statusMsg.textContent = target + ' cracked successfully. ' + crackedUsernames.length + ' of 5 accounts cracked.';
        statusMsg.className = 'status-message status-success';

        if (crackedUsernames.length === 5) {
            document.getElementById('flag-reveal-section').classList.add('revealed');
            document.getElementById('flag-reveal-section').scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
    } else {
        lines.push('Status: Exhausted, no match');
        output.textContent = lines.join('\n');
        output.style.color = 'var(--error)';
        statusMsg.textContent = 'No match for ' + target + ' with that wordlist and attack mode. Try a different combination.';
        statusMsg.className = 'status-message status-error';
    }
}

function addResultRow(entry, mode) {
    const emptyRow = document.getElementById('empty-results-row');
    if (emptyRow) emptyRow.remove();

    const tbody = document.getElementById('results-body');
    const row = document.createElement('tr');
    const modeLabel = mode === 'dictionary' ? 'Dictionary' : (mode === 'rule' ? 'Rule Based' : 'Mask');
    row.innerHTML = '<td class="username-cell">' + entry.username + '</td><td>' + entry.hashType + '</td><td>' + entry.password + '</td><td>' + modeLabel + '</td>';
    tbody.appendChild(row);
}

// ============================================================
// TUTORIAL SYSTEM (Spotlight based)
// ============================================================
const tutorialSteps = [
    { targetId: 'challenge-header', text: 'This is the Credential Cracking Terminal, a simulated hashcat style tool used after a penetration tester recovers a password hash dump.' },
    { targetId: 'hashdump-section', text: 'This is the leaked hash dump from Nexora Systems. Hash length and source tell you which algorithm and technique you are dealing with.' },
    { targetId: 'wordlist-section', text: 'Browse the available wordlists here. Picking the right one for the right account is most of the battle.' },
    { targetId: 'attack-mode-select', text: 'Choose an attack mode. Dictionary tries words as is, rule based mutates them with patterns like appended digits, mask targets a known character structure.' },
    { targetId: 'run-attack-btn', text: 'Launch the attack against your selected hash and wordlist. Watch the terminal for the result.' },
    { targetId: 'results-section', text: 'Every cracked password lands here. Crack all five accounts to unlock the flag.' }
];

let currentStep = 0;

function positionSpotlight(targetId) {
    const target = document.getElementById(targetId);
    if (!target) return;

    const rect = target.getBoundingClientRect();
    const isVisible = rect.top >= 0 && rect.bottom <= window.innerHeight;

    if (!isVisible) {
        target.scrollIntoView({ behavior: 'smooth', block: 'center' });
        setTimeout(() => drawSpotlight(target), 300);
    } else {
        drawSpotlight(target);
    }
}

function drawSpotlight(target) {
    const rect = target.getBoundingClientRect();
    const padding = 8;
    const spotlight = document.getElementById('spotlight-box');
    spotlight.style.display = 'block';
    spotlight.style.top = (rect.top - padding) + 'px';
    spotlight.style.left = (rect.left - padding) + 'px';
    spotlight.style.width = (rect.width + padding * 2) + 'px';
    spotlight.style.height = (rect.height + padding * 2) + 'px';

    const tooltip = document.getElementById('tooltip-card');
    tooltip.style.display = 'block';
    document.getElementById('tooltip-text').textContent = tutorialSteps[currentStep].text;

    let tooltipTop = rect.bottom + padding + 12;
    let tooltipLeft = rect.left;

    if (tooltipTop + 160 > window.innerHeight) {
        tooltipTop = rect.top - 160;
    }
    if (tooltipLeft + 300 > window.innerWidth) {
        tooltipLeft = window.innerWidth - 320;
    }
    if (tooltipLeft < 10) tooltipLeft = 10;

    tooltip.style.top = tooltipTop + 'px';
    tooltip.style.left = tooltipLeft + 'px';

    document.getElementById('tutorial-next-btn').textContent = (currentStep === tutorialSteps.length - 1) ? 'Finish' : 'Next';
}

function startTutorial() {
    currentStep = 0;
    positionSpotlight(tutorialSteps[currentStep].targetId);
}

function endTutorial() {
    document.getElementById('spotlight-box').style.display = 'none';
    document.getElementById('tooltip-card').style.display = 'none';
}

document.getElementById('tutorial-next-btn').addEventListener('click', function() {
    currentStep++;
    if (currentStep >= tutorialSteps.length) {
        endTutorial();
        document.getElementById('tutorial-modal-overlay').classList.add('active');
    } else {
        positionSpotlight(tutorialSteps[currentStep].targetId);
    }
});

document.getElementById('tutorial-skip-btn').addEventListener('click', function() {
    endTutorial();
});

document.getElementById('start-challenge-btn').addEventListener('click', function() {
    document.getElementById('tutorial-modal-overlay').classList.remove('active');
});

document.getElementById('view-tutorial-btn').addEventListener('click', function() {
    startTutorial();
});

window.addEventListener('resize', function() {
    const tooltip = document.getElementById('tooltip-card');
    if (tooltip.style.display === 'block') {
        positionSpotlight(tutorialSteps[currentStep].targetId);
    }
});

window.addEventListener('load', function() {
    setTimeout(startTutorial, 400);
});
</script>

</body>
</html>
